function crosswordTrace(grid, word) {
  const h = grid.length, w = grid[0].length;
  const extend = (path) => {
    if (path.length === word.length) return path.map(([r, c]) => grid[r][c]).join('') === word;
    const [r, c] = path[path.length - 1];
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nr >= h || nc < 0 || nc >= w || path.some(([pr, pc]) => pr === nr && pc === nc)) continue;
      if (extend([...path, [nr, nc]])) return true;
    }
    return false;
  };
  for (let r = 0; r < h; r++) for (let c = 0; c < w; c++) if (extend([[r, c]])) return true;
  return false;
}

function crosswordTrace(grid, word) {
  const h = grid.length, w = grid[0].length;
  const used = grid.map((row) => [...row].map(() => false));
  const walk = (r, c, i) => {
    if (r < 0 || r >= h || c < 0 || c >= w || used[r][c] || grid[r][c] !== word[i]) return false;
    if (i === word.length - 1) return true;
    used[r][c] = true;
    const found = walk(r + 1, c, i + 1) || walk(r - 1, c, i + 1) || walk(r, c + 1, i + 1) || walk(r, c - 1, i + 1);
    used[r][c] = false;
    return found;
  };
  for (let r = 0; r < h; r++) for (let c = 0; c < w; c++) if (walk(r, c, 0)) return true;
  return false;
}
